1	import { requireUser } from "@/lib/auth";
2	import { listHostingAccounts } from "@/lib/actions-hosting";
3	import { HostingClient } from "@/components/customer/HostingClient";
4	import { PageHeader } from "@/components/ui/primitives";
5	import { DeployButton } from "@/components/customer/DeployButton";
6	
7	export const dynamic = "force-dynamic";
8	
9	// Manage-existing view only. The order/checkout wizard now lives solely on
10	// /dashboard/deploy?product=hosting (the unified Deploy hub) — a single source of
11	// truth for the money-audited HostingDeployWizard. This page lists + manages the
12	// customer's existing accounts and links to the hub to deploy new sites.
13	//
14	// Redesigned 2026-08-29: swapped the old big decorative <PortalHero> banner for a
15	// plain <PageHeader> row (title + subtitle left, single CTA right) to match the
16	// approved mockup's denser, table-style overview — the account cards below were
17	// replaced by <HostingClient>'s summary stat card + plan table.
18	export default async function HostingPage() {
19	  await requireUser();
20	  const accounts = await listHostingAccounts();
21	  return (
22	    <>
23	      <PageHeader title="Shared Hosting" sub="Manage your sites, databases, email, and files — or deploy a new site from the hub.">
