1	import { requireUser } from "@/lib/auth";
2	
3	export const dynamic = "force-dynamic";
4	export const metadata = { title: "Matrix" };
5	
6	/**
7	 * Matrix route — intentionally a thin placeholder.
8	 *
9	 * The actual multi-console workspace is rendered by the PERSISTENT MatrixProvider
10	 * mounted at the portal shell level (components/portal/Shell.tsx →
11	 * components/customer/claude-code/MatrixProvider.tsx). That provider survives
12	 * in-portal navigation, so open consoles and their live server terminals are not
13	 * torn down when the customer moves between pages — which is impossible if the
14	 * workspace is mounted by this page, because the App Router unmounts a page's
15	 * subtree on every route change.
16	 *
17	 * This page still exists so the route is real (auth-gated, linkable, in the nav);
18	 * the provider's fixed panel covers this content while the route is active.
19	 */
20	export default async function BuildPage() {
21	  await requireUser();
22	  // The provider paints the workspace over this region. A short spacer keeps the
23	  // route from collapsing to zero height before the panel mounts.
24	  return <div className="min-h-[60vh]" aria-hidden />;
25	}
