1	import { notFound } from "next/navigation";
2	import { requireUser } from "@/lib/auth";
3	import { db } from "@/lib/db";
4	import { SiteEditor } from "@/components/customer/site-builder/SiteEditor";
5	import type { SiteRow } from "@/lib/actions-sites";
6	import { isSiteDocument, type SiteDocument } from "@/lib/site-render";
7	
8	export const dynamic = "force-dynamic";
9	
10	const BASE_DOMAIN = process.env.SITE_BUILDER_BASE_DOMAIN || "nxeon.site";
11	
12	export default async function SiteEditorPage({ params }: { params: Promise<{ id: string }> }) {
13	  const { id } = await params;
14	  const user = await requireUser();
15	
16	  const site = await db.site.findUnique({ where: { id } });
17	  // Ownership: a customer may only open their own site.
18	  if (!site || site.userId !== user.id) notFound();
19	
20	  const draft = await db.siteVersion.findFirst({
21	    where: { siteId: site.id, isDraft: true },
22	    orderBy: { createdAt: "desc" },
23	  });
24	  const document: SiteDocument | null =
25	    draft && isSiteDocument(draft.document) ? (draft.document as SiteDocument) : null;
26	
27	  const row: SiteRow = {
28	    id: site.id,
29	    name: site.name,
30	    slug: site.slug,
31	    status: site.status,
32	    templateKey: site.templateKey,
33	    publishedAt: site.publishedAt ? site.publishedAt.toISOString() : null,
34	    error: site.error,
35	    updatedAt: site.updatedAt.toISOString(),
36	  };
37	
38	  return <SiteEditor site={row} document={document} baseDomain={BASE_DOMAIN} />;
39	}
