1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { retryHostingProvision, recheckHostingHealth, type HostingAccountView } from "@/lib/actions-hosting";
6	import { termPriceCents } from "@/lib/billing-terms";
7	import { StatusDot, EmptyState, fmtMoney } from "@/components/ui/primitives";
8	import { MeterBar } from "@/components/ui/charts";
9	import { DeployButton } from "@/components/customer/DeployButton";
10	import {
11	  IconStack,
12	  IconGlobe,
13	  IconDb,
14	  IconDisk,
15	  IconMail,
16	  IconCalendar,
17	  IconExternal,
18	  IconDotsVertical,
19	  IconSearch,
20	  IconSliders,
21	} from "@/components/customer/hosting/OverviewIcons";
22	
23	const PAGE_SIZE = 10;
24	
25	type Tab = "all" | "active" | "expired";
26	
27	/* --------------------------------------------------------------- helpers --- */
28	
29	/**
30	 * Tier -> color mapping, keyed off the REAL HostingPlan.slug (falling back to
31	 * sortOrder for any tier this map hasn't seen yet, e.g. a future 4th plan). The
32	 * three tiers that exist today (prisma/seed-hosting-plans.ts): starter (sortOrder
33	 * 0), business (1), pro (2, the top/most expensive tier) — hence violet for the
34	 * entry tier, teal for the mid "Business" tier, and orange for the top "Pro" tier.
35	 */
36	const TIER_COLORS: Record<string, { icon: string; badge: string }> = {
37	  starter: { icon: "bg-gradient-to-br from-brand-500/30 to-brand-600/10 text-brand-300", badge: "border-brand-500/40 bg-brand-500/10 text-brand-300" },
38	  business: { icon: "bg-gradient-to-br from-teal-500/30 to-emerald-600/10 text-teal-300", badge: "border-teal-500/40 bg-teal-500/10 text-teal-300" },
39	  pro: { icon: "bg-gradient-to-br from-orange-500/30 to-orange-600/10 text-orange-300", badge: "border-orange-500/40 bg-orange-500/10 text-orange-300" },
40	};
41	const TIER_COLOR_RAMP = [
42	  { icon: "bg-gradient-to-br from-brand-500/30 to-brand-600/10 text-brand-300", badge: "border-brand-500/40 bg-brand-500/10 text-brand-300" },
43	  { icon: "bg-gradient-to-br from-accent-blue/30 to-blue-600/10 text-blue-300", badge: "border-blue-500/40 bg-blue-500/10 text-blue-300" },
44	  { icon: "bg-gradient-to-br from-teal-500/30 to-emerald-600/10 text-teal-300", badge: "border-teal-500/40 bg-teal-500/10 text-teal-300" },
45	  { icon: "bg-gradient-to-br from-orange-500/30 to-orange-600/10 text-orange-300", badge: "border-orange-500/40 bg-orange-500/10 text-orange-300" },
46	];
47	function tierColor(a: Pick<HostingAccountView, "planSlug" | "planSortOrder">) {
48	  return TIER_COLORS[a.planSlug] ?? TIER_COLOR_RAMP[a.planSortOrder % TIER_COLOR_RAMP.length];
49	}
50	
51	function fmtDate(iso: string | null): string {
52	  if (!iso) return "—";
53	  return new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
54	}
55	
56	/** Real per-cycle charge + its unit label — never hardcoded to "/month". Uses the
57	 *  SAME formula the renewal sweep actually bills (lib/billing-terms.termPriceCents)
58	 *  against the term + discount this account was SOLD on, so the number shown here
59	 *  matches what the customer is really charged at renewal. */
60	function termLabel(months: number): string {
61	  if (months === 1) return "/ month";
62	  if (months % 12 === 0) return months === 12 ? "/ year" : `/ ${months / 12} years`;
63	  return `/ ${months} mo`;
64	}
65	
66	function pct(used: number, total: number): number {
67	  if (!total || total <= 0) return 0;
68	  return Math.max(0, Math.min(100, (used / total) * 100));
69	}
70	
71	/** Extra sites (subdomains + addon domains) vs the plan's site budget — the exact
72	 *  same "extra sites" metric already shown on the account detail page's Overview
73	 *  tab (components/customer/hosting/HostingTabs.tsx QuotaTile), just aggregated /
74	 *  reused here. The primary domain is always live and isn't counted against the
75	 *  budget, matching that existing convention. */
76	function siteUsage(a: HostingAccountView) {
77	  return { used: a.subdomainsUsed + a.addonDomainsUsed, total: a.maxSites };
78	}
79	function dbUsage(a: HostingAccountView) {
80	  return { used: a.databasesUsed, total: a.maxDatabases };
81	}
82	function storageUsageMB(a: HostingAccountView) {
83	  return { used: a.diskUsedMB ?? 0, total: a.diskQuotaMB, measured: a.diskUsedMB != null };
84	}
85	
86	/* ---------------------------------------------------------------- widget --- */
87	
88	function MiniUsage({
89	  icon,
90	  label,
91	  used,
92	  total,
93	  color,
94	  unlimited = false,
95	  noUsageNote,
96	  format,
97	}: {
98	  icon: React.ReactNode;
99	  label: string;
100	  used: number;
101	  total: number;
102	  color: string;
103	  unlimited?: boolean;
104	  /** Set when there is no real "used" number for this dimension — renders the
105	   *  total only, with a note, and skips the bar rather than fabricating a used
106	   *  value. */
107	  noUsageNote?: string;
108	  format?: (n: number) => string;
109	}) {
110	  const f = format ?? ((n: number) => String(n));
111	  return (
112	    <div className="min-w-[92px]" title={noUsageNote}>
113	      <div className="flex items-center gap-1 text-[10px] font-medium uppercase tracking-wide text-slate-500">
114	        <span className="h-3 w-3 text-slate-500">{icon}</span>
115	        {label}
116	      </div>
117	      <div className="mt-0.5 text-xs font-semibold text-slate-200">
118	        {unlimited ? "Unlimited" : noUsageNote ? `${f(total)} incl.` : `${f(used)} / ${f(total)}`}
119	      </div>
120	      {!unlimited && !noUsageNote && (
121	        <div className="mt-1 w-20">
122	          <MeterBar value={used} max={total || 1} color={color} className="h-1.5" />
123	        </div>
124	      )}
125	    </div>
126	  );
127	}
128	
129	/* ------------------------------------------------------------------ menu --- */
130	
131	function RowMenu({
132	  a,
133	  onRetry,
134	  onRecheck,
135	}: {
136	  a: HostingAccountView;
137	  onRetry: () => void;
138	  onRecheck: () => void;
