341	  const [query, setQuery] = useState("");
342	  const [tierFilter, setTierFilter] = useState<string | null>(null);
343	  const [filterOpen, setFilterOpen] = useState(false);
344	  const [page, setPage] = useState(1);
345	  const filterRef = useRef<HTMLDivElement>(null);
346	
347	  useEffect(() => {
348	    if (!filterOpen) return;
349	    function onDoc(e: MouseEvent) {
350	      if (filterRef.current && !filterRef.current.contains(e.target as Node)) setFilterOpen(false);
351	    }
352	    document.addEventListener("mousedown", onDoc);
353	    return () => document.removeEventListener("mousedown", onDoc);
354	  }, [filterOpen]);
355	
356	  async function retry(id: string) {
357	    setError("");
358	    const res = await retryHostingProvision(id);
359	    if (res.error) {
360	      setError(res.error);
361	      return;
362	    }
363	    window.location.reload();
364	  }
365	
366	  async function recheck(id: string) {
367	    setError("");
368	    const res = await recheckHostingHealth(id);
369	    if (res.error) {
370	      setError(res.error);
371	      return;
372	    }
373	    window.location.reload();
374	  }
375	
376	  const tiers = useMemo(() => Array.from(new Set(accounts.map((a) => a.planName))).sort(), [accounts]);
377	
378	  // Bucket mapping for the tabs: HostingAccountStatus has no literal "EXPIRED"
379	  // state — an unpaid/past-due account is flipped to SUSPENDED by the renewal
380	  // sweep (worker/product-renewals.ts suspendUnpaidHostingAccount), so "Expired"
381	  // == SUSPENDED. PENDING/PROVISIONING/FAILED/DELETING accounts show under "All
382	  // Plans" only (they're neither a healthy active plan nor a lapsed one).
383	  const filtered = useMemo(() => {
384	    const q = query.trim().toLowerCase();
385	    return accounts.filter((a) => {
386	      if (tab === "active" && a.status !== "ACTIVE") return false;
387	      if (tab === "expired" && a.status !== "SUSPENDED") return false;
388	      if (tierFilter && a.planName !== tierFilter) return false;
389	      if (q && !a.primaryDomain.toLowerCase().includes(q) && !a.planName.toLowerCase().includes(q)) return false;
390	      return true;
391	    });
392	  }, [accounts, tab, tierFilter, query]);
393	
394	  useEffect(() => {
395	    setPage(1);
396	  }, [tab, tierFilter, query]);
397	
398	  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
399	  const clampedPage = Math.min(page, totalPages);
400	  const pageRows = filtered.slice((clampedPage - 1) * PAGE_SIZE, clampedPage * PAGE_SIZE);
401	
402	  // Fleet-wide summary — always over ALL of the customer's accounts (not the
403	  // current tab/search filter), so it reads as a stable "your whole hosting
404	  // footprint" tile rather than shifting under a filter.
405	  const activeCount = accounts.filter((a) => a.status === "ACTIVE").length;
406	  const sitesTotal = accounts.reduce((s, a) => s + siteUsage(a).total, 0);
407	  const sitesUsed = accounts.reduce((s, a) => s + siteUsage(a).used, 0);
408	  const dbTotal = accounts.reduce((s, a) => s + dbUsage(a).total, 0);
409	  const dbUsed = accounts.reduce((s, a) => s + dbUsage(a).used, 0);
410	  const storageTotalGB = accounts.reduce((s, a) => s + a.diskQuotaMB, 0) / 1024;
411	  const storageUsedGB = accounts.reduce((s, a) => s + (a.diskUsedMB ?? 0), 0) / 1024;
412	  const hasUnmeasuredStorage = accounts.some((a) => a.status === "ACTIVE" && a.diskUsedMB == null);
413	  const mailUnlimited = accounts.some((a) => a.planMailboxes === -1);
414	  const mailTotal = accounts.reduce((s, a) => s + Math.max(0, a.planMailboxes), 0);
415	
416	  if (accounts.length === 0) {
417	    return (
418	      <div className="space-y-8">
419	        {error && <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
420	        <EmptyState
421	          title="No hosting accounts yet"
422	          sub="Set up an isolated hosting account — on a free subdomain or your own domain — in a couple of minutes."
423	          action={<DeployButton href="/dashboard/deploy?product=hosting">Deploy your first site</DeployButton>}
424	        />
425	      </div>
426	    );
427	  }
428	
429	  return (
430	    <div className="space-y-6">
431	      {error && <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
432	
433	      {/* Summary stat card */}
434	      <div className="card overflow-hidden p-0">
435	        <div className="grid divide-y divide-white/[0.06] sm:grid-cols-2 sm:divide-x sm:divide-y-0 lg:grid-cols-5">
436	          <SummaryCell icon={<IconStack />} label="Active Plans" value={activeCount} statusDot />
437	          <SummaryCell
438	            icon={<IconGlobe />}
439	            label="Websites"
440	            value={`${sitesUsed} / ${sitesTotal}`}
441	            pctValue={pct(sitesUsed, sitesTotal)}
442	            color="#8a70fb"
443	          />
444	          <SummaryCell
445	            icon={<IconDb />}
446	            label="Databases"
447	            value={`${dbUsed} / ${dbTotal}`}
448	            pctValue={pct(dbUsed, dbTotal)}
449	            color="#3b82f6"
450	          />
451	          <SummaryCell
452	            icon={<IconDisk />}
453	            label="Storage"
454	            value={`${storageUsedGB.toFixed(storageUsedGB < 10 ? 1 : 0)} / ${storageTotalGB.toFixed(0)} GB`}
455	            pctValue={pct(storageUsedGB, storageTotalGB)}
456	            color="#22d3ee"
457	            note={hasUnmeasuredStorage ? "Some accounts are still measuring usage" : undefined}
458	          />
459	          <SummaryCell
460	            icon={<IconMail />}
461	            label="Emails"
462	            value={mailUnlimited ? "Unlimited" : `${mailTotal} incl.`}
463	            note="Mailbox usage isn't tracked for shared hosting yet"
464	          />
465	        </div>
466	      </div>
467	
468	      {/* Tabs + search row */}
469	      <div className="flex flex-wrap items-center justify-between gap-3">
470	        <div className="flex gap-1 rounded-xl border border-white/[0.08] bg-white/[0.03] p-1">
471	          {([
472	            { key: "all", label: "All Plans" },
473	            { key: "active", label: "Active" },
474	            { key: "expired", label: "Expired" },
475	          ] as { key: Tab; label: string }[]).map((t) => (
476	            <button
477	              key={t.key}
478	              type="button"
479	              onClick={() => setTab(t.key)}
480	              className={`rounded-lg px-3 py-1.5 text-xs font-semibold transition-colors ${
481	                tab === t.key ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white" : "text-slate-400 hover:text-white"
482	              }`}
483	            >
484	              {t.label}
485	            </button>
486	          ))}
487	        </div>
488	
489	        <div className="flex items-center gap-2">
490	          <div className="relative">
491	            <IconSearch className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500" />
492	            <input
493	              type="search"
494	              value={query}
495	              onChange={(e) => setQuery(e.target.value)}
496	              placeholder="Search plans..."
497	              className="input w-52 py-2 pl-9"
498	            />
499	          </div>
500	          <div className="relative" ref={filterRef}>
501	            <button
502	              type="button"
503	              aria-label="Filter by tier"
504	              onClick={() => setFilterOpen((o) => !o)}
505	              className={`btn-secondary p-2 ${tierFilter ? "border-brand-500/50 text-brand-300" : ""}`}
506	            >
507	              <IconSliders className="h-4 w-4" />
508	            </button>
509	            {filterOpen && (
510	              <div className="absolute right-0 top-full z-20 mt-1 w-44 rounded-xl border border-white/10 bg-navy-900 p-1.5 shadow-2xl">
511	                <button
512	                  type="button"
513	                  className={`block w-full rounded-lg px-3 py-1.5 text-left text-xs ${!tierFilter ? "bg-white/[0.06] text-white" : "text-slate-300 hover:bg-white/[0.06] hover:text-white"}`}
514	                  onClick={() => { setTierFilter(null); setFilterOpen(false); }}
515	                >
516	                  All tiers
517	                </button>
518	                {tiers.map((t) => (
519	                  <button
520	                    key={t}
521	                    type="button"
522	                    className={`block w-full rounded-lg px-3 py-1.5 text-left text-xs ${tierFilter === t ? "bg-white/[0.06] text-white" : "text-slate-300 hover:bg-white/[0.06] hover:text-white"}`}
523	                    onClick={() => { setTierFilter(t); setFilterOpen(false); }}
524	                  >
525	                    {t}
526	                  </button>
527	                ))}
528	              </div>
529	            )}
530	          </div>
531	        </div>
532	      </div>
533	
534	      {/* Table */}
535	      <div className="card overflow-hidden p-0">
536	        {pageRows.length === 0 ? (
537	          <div className="p-10 text-center text-sm text-slate-400">No hosting plans match your filters.</div>
538	        ) : (
539	          <div className="divide-y divide-white/[0.06]">
540	            {pageRows.map((a) => (
541	              <PlanRow key={a.id} a={a} onRetry={() => retry(a.id)} onRecheck={() => recheck(a.id)} />
542	            ))}
543	          </div>
544	        )}
545	      </div>
546	
547	      {/* Footer */}
548	      <div className="flex flex-wrap items-center justify-between gap-3 text-xs text-slate-500">
549	        <span>
