131	                WordPress installed — log in at <span className="font-mono">{wp.url}</span> · user <span className="font-mono">{wp.adminUser}</span> · password{" "}
132	                <span className="font-mono">{wp.adminPassword}</span> <span className="opacity-80">(also saved under App credentials)</span>
