57	/**
58	 * One-click app installer — a responsive grid of app logo tiles (WordPress first,
59	 * then the full catalog), styled like the VPS deploy wizard's OS picker. Selecting
60	 * a tile reveals an Install action; the install is enqueued as a hosting task and
61	 * the panel surfaces immediate, honest feedback: an "installing…" state, a live
62	 * queue below (so a SANDBOX/non-prod account still shows the queued/active task),
63	 * and, when the worker finishes, the resulting site + admin login. All security
64	 * lives in the server actions (ownership, DB caps, cross-tenant) — this is UI only.
65	 */
66	export function AppInstaller({ accountId }: { accountId: string }) {
67	  const [apps, setApps] = useState<AppItem[]>([]);
68	  const [selected, setSelected] = useState<string | null>(null);
69	  const [busy, setBusy] = useState(false);
70	  const [error, setError] = useState<string | null>(null);
71	  const [notice, setNotice] = useState<string | null>(null);
72	  const [tasks, setTasks] = useState<Task[]>([]);
73	
74	  useEffect(() => { listHostingAppMenu().then(setApps).catch(() => {}); }, []);
