76	  // Live view of this account's install tasks so a queued/running install is always
77	  // visible from the Apps tab itself (not only the Overview feed), including while a
78	  // SANDBOX/non-prod worker leaves it PENDING.
79	  useEffect(() => {
80	    let stop = false;
81	    const load = () =>
82	      listHostingTasks(accountId)
83	        .then((t) => { if (!stop) setTasks(t.filter((x) => x.kind === "WORDPRESS_INSTALL" || x.kind === "APP_INSTALL")); })
84	        .catch(() => {});
85	    load();
