105	        listHostingTasks(accountId)
106	          .then((t) => setTasks(t.filter((x) => x.kind === "WORDPRESS_INSTALL" || x.kind === "APP_INSTALL")))
107	          .catch(() => {});
108	      }
109	    } catch {
110	      setError("Something went wrong starting that install. Please try again.");
111	    } finally {
112	      setBusy(false);
113	    }
114	  }
115	
116	  return (
117	    <div className="space-y-4">
118	      {error && (
119	        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>
120	      )}
121	      {notice && (
122	        <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-200">{notice}</div>
123	      )}
124	
125	      <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3">
126	        {apps.map((ap) => {
127	          const active = selected === ap.slug;
128	          const featured = ap.slug === "wordpress";
129	          return (
130	            <button
131	              type="button"
132	              key={ap.slug}
133	              onClick={() => { setSelected(active ? null : ap.slug); setError(null); }}
134	              disabled={busy}
135	              aria-pressed={active}
136	              className={`card relative flex items-start gap-3 !p-3 text-left transition disabled:opacity-60 ${
137	                active ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"
138	              }`}
139	            >
140	              {featured && (
141	                <span className="absolute -top-2 right-2 rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider text-white shadow">
142	                  Recommended
143	                </span>
144	              )}
145	              <AppTileLogo slug={ap.slug} name={ap.name} logoPath={ap.logoPath} logoHex={ap.logoHex} />
146	              <div className="min-w-0 flex-1">
147	                <div className="flex items-center gap-2">
148	                  <span className="truncate text-sm font-semibold">{ap.name}</span>
149	                  {ap.needsDb ? (
150	                    <span className="shrink-0 rounded bg-brand-500/15 px-1.5 py-0.5 text-[10px] text-brand-200">database</span>
151	                  ) : (
152	                    <span className="shrink-0 rounded bg-emerald-500/15 px-1.5 py-0.5 text-[10px] text-emerald-300">no DB</span>
153	                  )}
154	                </div>
155	                <p className="mt-0.5 line-clamp-2 text-[11px] leading-snug text-slate-400">{ap.blurb}</p>
156	              </div>
157	              <span className={`mt-0.5 h-4 w-4 shrink-0 rounded-full border ${active ? "border-brand-400 bg-brand-500" : "border-white/20"}`} aria-hidden />
158	            </button>
159	          );
160	        })}
161	        {apps.length === 0 && <p className="col-span-full text-sm text-slate-500">Loading apps…</p>}
162	      </div>
163	
164	      {chosen && (
165	        <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-brand-400/40 bg-brand-500/[0.06] px-4 py-3">
166	          <div className="flex items-center gap-3">
167	            <AppTileLogo slug={chosen.slug} name={chosen.name} logoPath={chosen.logoPath} logoHex={chosen.logoHex} size={32} />
168	            <div>
169	              <p className="text-sm font-semibold">{chosen.name}</p>
170	              <p className="text-[11px] text-slate-400">
171	                {chosen.needsDb ? "A database will be created for you." : "No database needed."}
172	              </p>
173	            </div>
174	          </div>
175	          <button type="button" className="btn-primary px-3 py-1.5 text-sm" disabled={busy} onClick={() => install(chosen.slug)}>
176	            {busy ? "Installing…" : `Install ${chosen.name}`}
177	          </button>
178	        </div>
179	      )}
180	
181	      {tasks.length > 0 && (
182	        <div className="space-y-2">
183	          <h4 className="text-xs font-semibold uppercase tracking-wide text-slate-500">Installations</h4>
184	          {tasks.map((t) => {
