23	function fmtUptime(sec: number): string {
24	  if (!sec || sec <= 0) return "—";
25	  const d = Math.floor(sec / 86400);
26	  const h = Math.floor((sec % 86400) / 3600);
27	  const m = Math.floor((sec % 3600) / 60);
28	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
29	}
