244	function CronJobs({ serverId, running }: { serverId: string; running: boolean }) {
245	  const [rows, setRows] = useState<CronRow[] | null>(null);
246	  const [error, setError] = useState<string | null>(null);
247	  const [schedule, setSchedule] = useState("0 3 * * *");
248	  const [command, setCommand] = useState("");
249	  const [comment, setComment] = useState("");
250	  const [formError, setFormError] = useState<string | null>(null);
251	  const [pending, start] = useTransition();
252	
253	  const refresh = useCallback(async () => {
254	    const res = await listCronJobs(serverId);
255	    if (res.ok) setRows(res.cron);
256	    else setError(res.error);
257	  }, [serverId]);
258	
259	  useEffect(() => {
260	    void refresh();
261	  }, [refresh]);
262	
263	  useEffect(() => {
264	    if (!rows?.some((r) => ["PENDING", "DELETING"].includes(r.status))) return;
265	    const t = setInterval(() => void refresh(), 4000);
266	    return () => clearInterval(t);
267	  }, [rows, refresh]);
268	
269	  const add = () =>
270	    start(async () => {
271	      setFormError(null);
272	      const res = await createCronJob(serverId, schedule, command, comment || undefined);
273	      if (!res.ok) setFormError(res.error);
274	      else {
275	        setCommand("");
276	        setComment("");
277	        await refresh();
278	      }
279	    });
280	
281	  const act = (fn: () => Promise<{ ok: boolean; error?: string }>) =>
282	    start(async () => {
283	      setError(null);
284	      const res = await fn();
285	      if (!res.ok && res.error) setError(res.error);
286	      await refresh();
287	    });
288	
289	  return (
290	    <div className="space-y-6">
291	      <div className="card">
292	        <h3 className="mb-1 font-semibold">Add a cron job</h3>
293	        <p className="mb-4 text-sm text-slate-400">
294	          Schedules run as <code className="font-mono text-xs text-brand-300">root</code> in your VPS crontab.
295	        </p>
296	        <div className="grid gap-3">
297	          <div className="flex flex-wrap items-end gap-3">
298	            <div>
299	              <label className="label">Schedule</label>
300	              <input className="input w-40 font-mono" value={schedule} onChange={(e) => setSchedule(e.target.value)} disabled={pending || !running} />
301	            </div>
302	            <div>
303	              <label className="label">Preset</label>
304	              <select className="input w-52" value="" onChange={(e) => e.target.value && setSchedule(e.target.value)} disabled={pending || !running}>
305	                <option value="">Choose…</option>
306	                {CRON_PRESETS.map((p) => (
307	                  <option key={p.value} value={p.value}>
308	                    {p.label} ({p.value})
309	                  </option>
310	                ))}
311	              </select>
312	            </div>
313	            <div>
314	              <label className="label">Label (optional)</label>
315	              <input className="input w-48" value={comment} onChange={(e) => setComment(e.target.value)} disabled={pending || !running} maxLength={80} placeholder="nightly backup" />
316	            </div>
317	          </div>
318	          <div>
319	            <label className="label">Command</label>
320	            <input className="input font-mono" placeholder="/usr/bin/certbot renew --quiet" value={command} onChange={(e) => setCommand(e.target.value)} disabled={pending || !running} maxLength={500} />
321	          </div>
322	          <div>
323	            <button className="btn-primary" onClick={add} disabled={pending || !running || command.trim().length < 2}>
324	              {pending ? "Working…" : "Add cron job"}
325	            </button>
326	          </div>
327	        </div>
328	        {!running && <p className="mt-2 text-xs text-amber-300">Start the server to manage cron jobs.</p>}
329	        {formError && <p className="mt-2 text-sm text-red-400">{formError}</p>}
330	      </div>
331	
332	      <div className="card p-0">
333	        <p className="section-label px-4 pt-4">Cron jobs</p>
334	        {error && <p className="px-4 pt-3 text-sm text-red-400">{error}</p>}
335	        {rows === null ? (
336	          <LoadingRows />
337	        ) : rows.length === 0 ? (
338	          <EmptyState title="No cron jobs" hint="Schedule recurring commands — backups, cert renewals, cleanup." />
339	        ) : (
340	          <table className="table-shell mt-2">
341	            <thead>
342	              <tr>
343	                <th>Schedule</th>
344	                <th>Command</th>
345	                <th>Status</th>
346	                <th className="text-right">Actions</th>
347	              </tr>
348	            </thead>
349	            <tbody>
350	              {rows.map((r) => {
351	                const busy = ["PENDING", "DELETING"].includes(r.status);
352	                return (
353	                  <tr key={r.id} className={r.enabled ? "" : "opacity-60"}>
354	                    <td className="font-mono text-xs text-slate-100">{r.schedule}</td>
355	                    <td>
356	                      {r.comment && <div className="text-[11px] text-slate-500">{r.comment}</div>}
357	                      <div className="max-w-md truncate font-mono text-xs text-slate-300" title={r.command}>{r.command}</div>
358	                    </td>
359	                    <td>
360	                      <StatusPill status={r.status} />
361	                      {!r.enabled && r.status !== "PENDING" && <span className="ml-1 text-[11px] text-slate-500">paused</span>}
362	                      {r.error && <div className="mt-1 max-w-xs truncate text-[11px] text-red-400" title={r.error}>{r.error}</div>}
363	                    </td>
364	                    <td>
365	                      <div className="flex items-center justify-end gap-1.5">
366	                        <button className="btn-secondary px-2.5 py-1 text-xs" disabled={pending || busy} onClick={() => act(() => toggleCronJob(r.id))}>
367	                          {r.enabled ? "Pause" : "Resume"}
368	                        </button>
369	                        <button
370	                          className="btn-danger px-2.5 py-1 text-xs"
371	                          disabled={pending || busy}
372	                          onClick={() => {
373	                            if (window.confirm("Delete this cron job?")) act(() => deleteCronJob(r.id));
374	                          }}
375	                        >
376	                          Delete
377	                        </button>
378	                      </div>
379	                    </td>
380	                  </tr>
381	                );
382	              })}
383	            </tbody>
384	          </table>
385	        )}
386	      </div>
387	    </div>
388	  );
389	}
