3	/**
4	 * GrapesJS editor wrapper for the Website Builder.
5	 *
6	 * GrapesJS touches `window`/DOM, so it is imported dynamically INSIDE a useEffect
7	 * (never at module top level) and only ever runs in the browser. The published
8	 * output is the editor's static export — `editor.getHtml()` + `editor.getCss()` —
9	 * and the reloadable draft is `editor.getProjectData()`, both persisted through
10	 * the ownership-checked `saveDraft` server action as a SiteDocument.
11	 *
12	 * The MVP editor edits the site's home page ("/"). Other pages a template ships
13	 * with are preserved untouched in the saved document.
14	 */
15	import "grapesjs/dist/css/grapes.min.css";
16	import { useEffect, useRef, useState } from "react";
17	import { useRouter } from "next/navigation";
18	import type { Editor } from "grapesjs";
19	import { saveDraft, publishSite, type SiteRow } from "@/lib/actions-sites";
20	import type { SiteDocument, SitePageDoc } from "@/lib/site-render";
21	
22	export function SiteEditor({
23	  site,
24	  document: initialDoc,
25	  baseDomain,
26	}: {
27	  site: SiteRow;
28	  document: SiteDocument | null;
29	  baseDomain: string;
30	}) {
31	  const router = useRouter();
32	  const holderRef = useRef<HTMLDivElement | null>(null);
33	  const editorRef = useRef<Editor | null>(null);
34	  // Pages OTHER than "/" are kept verbatim and re-merged on save.
35	  const otherPagesRef = useRef<SitePageDoc[]>([]);
36	  const [ready, setReady] = useState(false);
37	  const [status, setStatus] = useState<string | null>(null);
38	  const [busy, setBusy] = useState(false);
39	
40	  useEffect(() => {
41	    let editor: Editor | null = null;
42	    let cancelled = false;
43	
44	    (async () => {
45	      const grapesjs = (await import("grapesjs")).default;
46	      const preset = (await import("grapesjs-preset-webpage")).default;
47	      if (cancelled || !holderRef.current) return;
48	
49	      const pages = initialDoc?.pages ?? [];
50	      const home = pages.find((p) => p.path === "/") ?? pages[0];
51	      otherPagesRef.current = pages.filter((p) => p !== home);
52	
53	      editor = grapesjs.init({
54	        container: holderRef.current,
55	        height: "100%",
56	        fromElement: false,
57	        storageManager: false, // we persist via the saveDraft server action
58	        // GrapesJS ships a device manager (desktop / tablet / mobile) — the
59	        // responsive breakpoint switcher the MVP requires.
60	        deviceManager: {
61	          devices: [
62	            { name: "Desktop", width: "" },
63	            { name: "Tablet", width: "768px", widthMedia: "992px" },
64	            { name: "Mobile", width: "375px", widthMedia: "575px" },
65	          ],
66	        },
67	        plugins: [preset as unknown as (e: Editor) => void],
68	        pluginsOpts: {},
69	      });
70	
71	      // Load the existing draft: prefer the reloadable project blob, else import
72	      // the raw template HTML+CSS.
73	      const projectData = (home as SitePageDoc | undefined)?.projectData;
74	      if (projectData && typeof projectData === "object") {
75	        editor.loadProjectData(projectData as Record<string, unknown>);
76	      } else if (home) {
77	        editor.setComponents(home.html || "");
78	        editor.setStyle(home.css || "");
79	      }
80	
81	      editorRef.current = editor;
82	      if (!cancelled) setReady(true);
83	    })();
84	
85	    return () => {
86	      cancelled = true;
87	      try {
88	        editor?.destroy();
89	      } catch {
90	        /* best effort */
91	      }
92	      editorRef.current = null;
93	    };
94	    // Initialise once for this site; initialDoc is a snapshot at mount time.
95	    // eslint-disable-next-line react-hooks/exhaustive-deps
96	  }, []);
97	
98	  function currentDocument(): SiteDocument {
99	    const editor = editorRef.current;
100	    const home = initialDoc?.pages.find((p) => p.path === "/");
101	    const homePage: SitePageDoc = {
102	      path: "/",
103	      title: home?.title,
104	      seoDesc: home?.seoDesc,
105	      html: editor ? editor.getHtml() : home?.html ?? "",
106	      css: editor ? editor.getCss({}) ?? "" : home?.css ?? "",
107	      projectData: editor ? editor.getProjectData() : home?.projectData,
108	    };
109	    return { pages: [homePage, ...otherPagesRef.current] };
110	  }
111	
112	  async function doSave(): Promise<boolean> {
113	    const res = await saveDraft(site.id, currentDocument());
114	    if (!res.ok) {
115	      setStatus(res.error);
116	      return false;
117	    }
118	    setStatus("Draft saved.");
119	    return true;
120	  }
121	
122	  function onSave() {
123	    setBusy(true);
124	    setStatus(null);
125	    doSave().finally(() => setBusy(false));
126	  }
127	
128	  function onPublish() {
129	    setBusy(true);
130	    setStatus(null);
131	    (async () => {
132	      const saved = await doSave();
133	      if (!saved) return;
134	      const res = await publishSite(site.id);
135	      if (!res.ok) {
136	        setStatus(res.error);
137	        return;
138	      }
139	      setStatus("Publishing… this can take a moment.");
140	      router.push("/dashboard/sites");
141	    })().finally(() => setBusy(false));
142	  }
143	
144	  const domain = `${site.slug}.${baseDomain}`;
145	
146	  return (
147	    <div className="flex h-[calc(100vh-4rem)] flex-col">
148	      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/10 px-4 py-3">
149	        <div className="min-w-0">
150	          <div className="truncate text-sm font-semibold">{site.name}</div>
151	          <div className="text-xs text-slate-400">{domain}</div>
152	        </div>
153	        <div className="flex items-center gap-2">
154	          {status && <span className="text-xs text-slate-400">{status}</span>}
155	          <button
156	            type="button"
157	            onClick={() => router.push("/dashboard/sites")}
158	            className="rounded-lg border border-white/10 px-3 py-1.5 text-sm hover:border-white/25"
159	          >
160	            Back
161	          </button>
162	          <button
163	            type="button"
164	            onClick={onSave}
165	            disabled={!ready || busy}
166	            className="rounded-lg border border-white/10 px-3 py-1.5 text-sm hover:border-white/25 disabled:opacity-50"
167	          >
168	            Save draft
169	          </button>
170	          <button
171	            type="button"
172	            onClick={onPublish}
173	            disabled={!ready || busy}
174	            className="rounded-lg bg-brand-500 px-4 py-1.5 text-sm font-semibold text-white disabled:opacity-50"
175	          >
176	            Publish
177	          </button>
178	        </div>
179	      </div>
180	      <div className="relative flex-1 overflow-hidden">
181	        {!ready && (
182	          <div className="absolute inset-0 flex items-center justify-center text-sm text-slate-400">
183	            Loading editor…
184	          </div>
185	        )}
186	        <div ref={holderRef} className="h-full" />
187	      </div>
188	    </div>
189	  );
190	}
