1	"use client";
2	
3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { useEffect, useState } from "react";
6	import { BuildStudio } from "./BuildStudio";
7	import type { BoardBuild } from "./PipelineBoard";
8	import { matrixWorkspaceData } from "@/lib/actions-claude-console";
9	
10	/**
11	 * Portal-wide, PERSISTENT Matrix workspace.
12	 *
13	 * Mounted ONCE at the portal shell level (components/portal/Shell.tsx), exactly
14	 * like the terminal dock and the mail composer. Because the App Router keeps
15	 * Shell mounted across in-portal navigation, the whole Matrix subtree — every
16	 * open console, its per-console transcript/input state, and any live server
17	 * terminal websocket inside it — survives moving between dashboard pages. Leave
18	 * Matrix mid-build, wander the portal, come back, and it is exactly as you left
19	 * it (the sidebar "running"/"update" tag tells you when to come back).
20	 *
21	 * How it stays alive:
22	 *   - The workspace is rendered into a fixed panel that occupies the main
23	 *     content region ONLY while the route is /dashboard/build; on every other
24	 *     route the panel is `display:none` but STILL MOUNTED, so React never
25	 *     unmounts BuildStudio/BuildConsole and their sockets keep running.
26	 *   - It is lazy: nothing is fetched or mounted until the customer first opens
27	 *     Matrix (`activated` latches true), so users who never touch it pay nothing.
28	 *   - Data (servers, recent builds, key status) is re-fetched each time the
29	 *     route is entered and passed as fresh props. BuildStudio's console state
30	 *     lives in its own `useState` (initialised once), so refreshed props update
31	 *     the dropdowns/board without ever resetting the open consoles.
32	 *
33	 * The /dashboard/build PAGE is a thin placeholder — this panel covers it.
34	 */
35	
36	const BUILD_ROUTE = "/dashboard/build";
37	
38	type WorkspaceData = {
39	  servers: { id: string; hostname: string }[];
40	  recentBuilds: BoardBuild[];
41	  keyConnected: boolean;
42	};
43	
44	export function MatrixProvider({ children }: { children: React.ReactNode }) {
45	  const pathname = usePathname();
46	  const onRoute = pathname === BUILD_ROUTE;
47	
48	  // Latches true the first time the workspace is opened; keeps the panel mounted
49	  // forever after (hidden off-route) so sessions persist.
50	  const [activated, setActivated] = useState(false);
51	  const [data, setData] = useState<WorkspaceData | null>(null);
52	  const [error, setError] = useState<string | null>(null);
53	
54	  useEffect(() => {
55	    if (onRoute) setActivated(true);
56	  }, [onRoute]);
57	
58	  // Fetch on every entry to the route. The first fetch also flips the panel from
59	  // its loading state; later ones just refresh props (console state is retained).
60	  useEffect(() => {
61	    if (!onRoute) return;
62	    let alive = true;
63	    setError(null);
64	    matrixWorkspaceData()
65	      .then((d) => {
66	        if (alive) setData(d);
67	      })
68	      .catch(() => {
69	        if (alive && !data) setError("Couldn't load your Matrix workspace. Try reloading the page.");
70	      });
71	    return () => {
72	      alive = false;
73	    };
74	    // Intentionally keyed only on the route: re-fetch each time we land here.
75	    // eslint-disable-next-line react-hooks/exhaustive-deps
76	  }, [onRoute]);
77	
78	  return (
79	    <>
80	      {children}
81	      {activated && (
82	        <div
83	          // Covers the main content region: below the sticky header (h-16), right
84	          // of the rail (Shell publishes --nx-rail-w; 15rem uncollapsed default).
85	          // z-10 sits under the sticky header (z-20) so the top bar stays usable.
86	          className="fixed inset-x-0 bottom-0 top-16 z-10 overflow-y-auto bg-navy-950 lg:left-[var(--nx-rail-w,15rem)]"
87	          style={{ display: onRoute ? "block" : "none" }}
88	          aria-hidden={!onRoute}
89	        >
90	          <div className="mx-auto w-full max-w-7xl px-4 py-8 sm:px-6">
91	            {error ? (
92	              <div className="card p-8 text-center">
93	                <p className="text-sm text-red-300">{error}</p>
94	              </div>
95	            ) : !data ? (
96	              <div className="flex min-h-[50vh] items-center justify-center text-sm text-slate-400">
97	                <span className="inline-flex items-center gap-2">
98	                  <span className="h-2 w-2 animate-pulse rounded-full bg-brand-400" />
99	                  Opening Matrix…
100	                </span>
101	              </div>
102	            ) : data.servers.length === 0 ? (
103	              <div className="space-y-6">
104	                <div>
105	                  <h1 className="page-title">Matrix</h1>
106	                  <p className="mt-1 text-sm text-slate-400">
107	                    Open several AI build consoles at once — build with your Anthropic key, or with
108	                    Claude running on your own server.
109	                  </p>
110	                </div>
111	                <div className="card flex flex-col items-center justify-center py-14 text-center">
112	                  <h3 className="text-base font-semibold">No running servers</h3>
113	                  <p className="mt-1 max-w-sm text-sm text-slate-400">
114	                    Matrix builds on a running server. Start or deploy one, then come back here.
115	                  </p>
116	                  <Link href="/dashboard/servers" className="btn-primary mt-5">
117	                    Go to servers
118	                  </Link>
119	                </div>
120	              </div>
121	            ) : (
122	              <BuildStudio
123	                servers={data.servers}
124	                recentBuilds={data.recentBuilds}
125	                keyConnected={data.keyConnected}
126	              />
127	            )}
128	          </div>
129	        </div>
130	      )}
131	    </>
132	  );
133	}
