3	import { consolePhase, type ConsolePhase } from "@/lib/claude-console-core";
4	
5	/**
6	 * A lightweight per-project pipeline board.
7	 *
8	 * IMPORTANT (this codebase's cardinal rule): every card is placed by the build's
9	 * REAL, tracked `status` — there is no stage this board reports that the backend
10	 * does not actually track. The columns are just a view over ClaudeBuild.status
11	 * (the same field the console polls), so a card in "Running" is a build whose row
12	 * says RUNNING. Nothing here invents progress it did not verify.
13	 */
14	
15	export type BoardBuild = {
16	  id: string;
17	  status: string;
18	  steps: number;
19	  prompt: string;
20	  title: string | null;
21	  mirrorGroupId: string | null;
22	  createdAt: string;
23	  hostname: string;
24	};
25	
26	// Board stages, each backed one-to-one by a real console phase.
27	const STAGES: { phase: ConsolePhase; label: string; dot: string }[] = [
28	  { phase: "planning", label: "Planning", dot: "bg-amber-400" },
29	  { phase: "awaiting", label: "Awaiting approval", dot: "bg-sky-400" },
30	  { phase: "running", label: "Running", dot: "bg-brand-400" },
31	  { phase: "done", label: "Done", dot: "bg-emerald-400" },
32	  { phase: "failed", label: "Failed", dot: "bg-red-500" },
33	];
34	
35	export function PipelineBoard({ builds }: { builds: BoardBuild[] }) {
36	  // Bucket each build by its real status → phase. "idle" builds (none, in
37	  // practice) are simply not shown — we never place a card in a stage its
38	  // status doesn't map to.
39	  const byPhase = new Map<ConsolePhase, BoardBuild[]>();
40	  for (const b of builds) {
41	    const p = consolePhase(b.status);
42	    if (p === "idle") continue;
43	    const arr = byPhase.get(p) ?? [];
44	    arr.push(b);
45	    byPhase.set(p, arr);
46	  }
47	
48	  if (builds.length === 0) {
49	    return (
50	      <div className="card p-6 text-center text-sm text-slate-400">
51	        No builds yet. Start one in a console and it will appear here, tracked by its real status.
52	      </div>
53	    );
54	  }
55	
56	  return (
57	    <div className="card p-4">
58	      <div className="mb-3 flex items-center justify-between">
59	        <h2 className="text-sm font-semibold text-slate-200">Build pipeline</h2>
60	        <span className="text-[11px] text-slate-500">Cards reflect each build&apos;s live status.</span>
61	      </div>
62	      <div className="grid gap-3 md:grid-cols-3 xl:grid-cols-5">
63	        {STAGES.map((stage) => {
64	          const items = byPhase.get(stage.phase) ?? [];
65	          return (
66	            <div key={stage.phase} className="rounded-xl border border-white/[0.06] bg-navy-950/50 p-2.5">
67	              <div className="mb-2 flex items-center gap-1.5 px-0.5">
68	                <span className={`h-2 w-2 rounded-full ${stage.dot}`} />
69	                <span className="text-[11px] font-semibold uppercase tracking-wider text-slate-400">{stage.label}</span>
70	                <span className="ml-auto text-[11px] text-slate-500">{items.length}</span>
71	              </div>
72	              <div className="space-y-2">
73	                {items.length === 0 ? (
74	                  <p className="px-1 py-2 text-[11px] text-slate-600">—</p>
75	                ) : (
76	                  items.map((b) => (
77	                    <div key={b.id} className="rounded-lg border border-white/[0.06] bg-white/[0.03] p-2">
78	                      <p className="line-clamp-2 text-[12px] text-slate-200" title={b.prompt}>
79	                        {b.title ? <span className="font-semibold text-brand-200">{b.title}: </span> : null}
80	                        {b.prompt}
81	                      </p>
82	                      <div className="mt-1.5 flex flex-wrap items-center gap-1.5 text-[10px] text-slate-500">
83	                        <span className="truncate">{b.hostname}</span>
84	                        {b.status === "RUNNING" && <span>· step {b.steps}</span>}
85	                        {b.mirrorGroupId && (
86	                          <span className="rounded border border-brand-400/30 bg-brand-500/10 px-1 text-brand-200">mirror</span>
87	                        )}
88	                      </div>
89	                    </div>
90	                  ))
91	                )}
92	              </div>
93	            </div>
94	          );
95	        })}
96	      </div>
97	    </div>
98	  );
99	}
