33	export function ClaudeBuilder({ servers }: { servers: ServerOption[] }) {
34	  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
35	  const [prompt, setPrompt] = useState("");
36	  const [error, setError] = useState<string | null>(null);
37	  const [buildId, setBuildId] = useState<string | null>(null);
38	  const [state, setState] = useState<BuildState | null>(null);
39	  const [pending, startTransition] = useTransition();
40	  const logRef = useRef<HTMLPreElement>(null);
41	
42	  // Poll the build status while a build is active (until it reaches DONE/FAILED).
43	  useEffect(() => {
44	    if (!buildId) return;
45	    let alive = true;
46	    let timer: ReturnType<typeof setTimeout>;
47	
48	    const tick = async () => {
49	      try {
50	        const res = await fetch(`/api/claude/${buildId}`, { cache: "no-store" });
51	        if (res.ok) {
52	          const data = (await res.json()) as BuildState;
53	          if (alive) setState(data);
54	          if (data.status && TERMINAL.has(data.status)) return; // stop polling
55	        }
56	      } catch {
57	        /* transient — keep polling */
58	      }
59	      if (alive) timer = setTimeout(tick, 2000);
60	    };
61	    void tick();
62	    return () => {
63	      alive = false;
64	      clearTimeout(timer);
65	    };
66	  }, [buildId]);
67	
68	  // Keep the log scrolled to the bottom as it streams.
69	  useEffect(() => {
70	    if (logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight;
71	  }, [state?.log]);
72	
73	  const status = state?.status ?? null;
74	  const inProgress = Boolean(buildId) && !(status && TERMINAL.has(status));
75	  const awaitingApproval = status === "AWAITING_APPROVAL";
76	  const planning = status === "QUEUED" || status === "PLANNING";
77	  const executing = status === "RUNNING";
78	  const plan = parsePlan(state?.plan);
79	
80	  const onSubmit = (e: React.FormEvent) => {
81	    e.preventDefault();
82	    setError(null);
83	    startTransition(async () => {
84	      const res = await submitBuild(serverId, prompt);
85	      if (res.error) {
86	        setError(res.error);
87	        return;
88	      }
89	      if (res.buildId) {
90	        setBuildId(res.buildId);
91	        setState({ status: "QUEUED", steps: 0, log: "", plan: null });
92	      }
93	    });
94	  };
95	
96	  const onApprove = () => {
97	    if (!buildId) return;
98	    setError(null);
99	    startTransition(async () => {
100	      const res = await approveBuild(buildId);
101	      if (res.error) {
102	        setError(res.error);
103	        return;
104	      }
105	      // Optimistically flip to QUEUED; polling will pick up RUNNING → DONE.
106	      setState((s) => (s ? { ...s, status: "QUEUED" } : s));
107	    });
108	  };
109	
110	  const onReject = () => {
111	    if (!buildId) return;
112	    setError(null);
113	    startTransition(async () => {
114	      const res = await rejectBuild(buildId);
115	      if (res.error) {
116	        setError(res.error);
117	        return;
118	      }
119	      setState((s) => (s ? { ...s, status: "FAILED" } : s));
120	    });
121	  };
122	
123	  const reset = () => {
124	    setBuildId(null);
125	    setState(null);
126	    setPrompt("");
127	    setError(null);
128	  };
129	
130	  const statusTone =
131	    status === "DONE"
132	      ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-300"
133	      : status === "FAILED"
134	      ? "border-red-500/40 bg-red-500/10 text-red-300"
135	      : status === "AWAITING_APPROVAL"
136	      ? "border-sky-500/40 bg-sky-500/10 text-sky-300"
137	      : "border-amber-500/40 bg-amber-500/10 text-amber-300";
138	
139	  return (
140	    <div className="space-y-6">
141	      <form onSubmit={onSubmit} className="card space-y-4 p-5">
142	        <div>
143	          <label className="mb-1.5 block text-sm font-medium text-slate-300">Server</label>
144	          <select
145	            className="input"
146	            value={serverId}
147	            onChange={(e) => setServerId(e.target.value)}
148	            disabled={inProgress || pending}
149	          >
150	            {servers.map((s) => (
151	              <option key={s.id} value={s.id}>
152	                {s.hostname}
153	              </option>
154	            ))}
155	          </select>
156	        </div>
157	
158	        <div>
159	          <label className="mb-1.5 block text-sm font-medium text-slate-300">
160	            What should Claude build?
161	          </label>
162	          <textarea
163	            className="input min-h-[110px] resize-y font-normal"
164	            placeholder="e.g. Install and configure a Node.js app served behind nginx with a firewall."
