61	type SpeechRecognitionEvent = { results: ArrayLike<SpeechResult>; resultIndex?: number };
62	
63	type SpeechRecognitionLike = {
64	  lang: string;
65	  continuous: boolean;
66	  interimResults: boolean;
67	  start: () => void;
68	  stop: () => void;
69	  onresult: ((e: SpeechRecognitionEvent) => void) | null;
70	  onerror: ((e: { error?: string }) => void) | null;
