74	function getSpeechRecognitionCtor(): (new () => SpeechRecognitionLike) | null {
75	  if (typeof window === "undefined") return null;
76	  const w = window as unknown as {
77	    SpeechRecognition?: new () => SpeechRecognitionLike;
78	    webkitSpeechRecognition?: new () => SpeechRecognitionLike;
79	  };
80	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
81	}
82	
83	/**
84	 * Live voice equalizer. Given the active mic MediaStream it draws a few bars
85	 * that react to the real audio level via a Web Audio AnalyserNode — the visible
86	 * "it's hearing you" cue while dictating. Owns its own rAF + AudioContext and
87	 * tears them down when the stream goes away. Renders nothing (a flat bar) when
88	 * no stream is available (mic blocked) so the layout never jumps.
89	 */
90	function VoiceMeter({ stream }: { stream: MediaStream | null }) {
91	  const canvasRef = useRef<HTMLCanvasElement>(null);
92	
93	  useEffect(() => {
94	    if (!stream) return;
95	    const canvas = canvasRef.current;
96	    if (!canvas) return;
97	    const ctx2d = canvas.getContext("2d");
98	    if (!ctx2d) return;
99	
100	    let raf = 0;
101	    let audioCtx: AudioContext | null = null;
102	    try {
103	      const AC =
104	        window.AudioContext ||
105	        (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
106	      if (!AC) return;
107	      audioCtx = new AC();
108	      const src = audioCtx.createMediaStreamSource(stream);
109	      const analyser = audioCtx.createAnalyser();
110	      analyser.fftSize = 128;
111	      analyser.smoothingTimeConstant = 0.75;
112	      src.connect(analyser);
113	      const bins = new Uint8Array(analyser.frequencyBinCount);
114	      const BARS = 5;
115	      const step = Math.max(1, Math.floor(bins.length / BARS));
116	
117	      const draw = () => {
118	        analyser.getByteFrequencyData(bins);
119	        const w = canvas.width;
120	        const h = canvas.height;
121	        ctx2d.clearRect(0, 0, w, h);
122	        const bw = w / BARS;
123	        for (let i = 0; i < BARS; i++) {
124	          let sum = 0;
125	          for (let j = 0; j < step; j++) sum += bins[i * step + j] ?? 0;
126	          const v = sum / step / 255; // 0..1
127	          const bh = Math.max(2, v * h);
128	          ctx2d.fillStyle = "#8a70fb";
129	          ctx2d.fillRect(i * bw + bw * 0.25, (h - bh) / 2, bw * 0.5, bh);
130	        }
131	        raf = requestAnimationFrame(draw);
132	      };
133	      draw();
134	    } catch {
135	      /* no meter */
136	    }
137	
138	    return () => {
139	      if (raf) cancelAnimationFrame(raf);
140	      try {
141	        void audioCtx?.close();
142	      } catch {
143	        /* ignore */
144	      }
145	    };
146	  }, [stream]);
147	
148	  return <canvas ref={canvasRef} width={46} height={16} className="h-4 w-[46px]" aria-hidden />;
149	}
