383	    },
384	    [addFiles]
385	  );
386	
387	  /* ------------------------------- voice ---------------------------------- */
388	
389	  // Stop dictation: release the recognizer, kill the mic stream (and its
390	  // equalizer), and drop the "listening" state. Idempotent.
391	  const stopVoice = useCallback(() => {
392	    wantVoiceRef.current = false;
393	    try {
394	      recognitionRef.current?.stop();
395	    } catch {
396	      /* ignore */
397	    }
398	    if (voiceStreamRef.current) {
399	      for (const t of voiceStreamRef.current.getTracks()) {
400	        try {
401	          t.stop();
402	        } catch {
403	          /* ignore */
404	        }
405	      }
406	      voiceStreamRef.current = null;
407	    }
408	    setVoiceStream(null);
409	    setListening(false);
410	  }, []);
411	
412	  // Live, Claude-style dictation: interim words stream into the box as spoken,
413	  // and the session keeps listening (auto-restarting across pauses) until the
414	  // user stops it. A separate mic stream feeds the equalizer so the button
415	  // visibly reacts to the voice.
416	  const toggleVoice = useCallback(async () => {
417	    const Ctor = getSpeechRecognitionCtor();
418	    if (!Ctor) {
