432	      voiceStreamRef.current = stream;
433	      setVoiceStream(stream);
434	    } catch {
435	      /* meter is optional */
436	    }
437	
438	    // Text already in the box is preserved; dictation appends after it.
439	    voiceBaseRef.current = input;
440	    voiceCommittedRef.current = input;
441	    wantVoiceRef.current = true;
442	
443	    const rec = new Ctor();
444	    rec.lang = "en-US";
445	    rec.continuous = true;
446	    rec.interimResults = true;
447	    rec.onresult = (ev) => {
448	      // With interim results the `results` list is cumulative for this segment —
449	      // concatenate every alternative to get the full spoken text so far.
450	      let spoken = "";
451	      for (let i = 0; i < ev.results.length; i++) spoken += ev.results[i][0].transcript;
452	      const base = voiceBaseRef.current;
453	      const next = (base ? base + " " : "") + spoken.trim();
454	      voiceCommittedRef.current = next;
455	      setInput(next);
456	    };
457	    rec.onerror = (e) => {
458	      const code = e?.error ?? "";
459	      if (code === "not-allowed" || code === "service-not-allowed") {
460	        setVoiceError("Microphone access is blocked. Allow it for this site in your browser settings, then try again.");
461	        stopVoice();
462	      } else if (code === "audio-capture") {
463	        setVoiceError("No microphone was found. Check that one is connected.");
464	        stopVoice();
465	      } else if (code && code !== "no-speech" && code !== "aborted") {
466	        setVoiceError("Voice input isn't available right now.");
467	        stopVoice();
468	      }
469	      // no-speech/aborted: let onend decide whether to keep listening.
470	    };
471	    rec.onend = () => {
472	      // Chrome ends a segment on a pause even with continuous=true. Restart while
473	      // the user still wants to dictate so it behaves like a held session; carry
474	      // the already-captured text forward as the new base.
475	      if (wantVoiceRef.current) {
476	        voiceBaseRef.current = voiceCommittedRef.current;
