3	import { useCallback, useEffect, useRef, useState } from "react";
4	
5	/* -------------------------------------------------------------------------- */
6	/* Web Speech API (voice-to-text) — typed minimally, degrades gracefully.      */
7	/* -------------------------------------------------------------------------- */
8	
9	type SpeechAlternative = { transcript: string };
10	type SpeechResult = ArrayLike<SpeechAlternative> & { isFinal?: boolean };
11	type SpeechRecognitionEvent = { results: ArrayLike<SpeechResult>; resultIndex?: number };
12	type SpeechRecognitionLike = {
13	  lang: string;
14	  continuous: boolean;
15	  interimResults: boolean;
16	  start: () => void;
17	  stop: () => void;
18	  onresult: ((e: SpeechRecognitionEvent) => void) | null;
19	  onerror: ((e: { error?: string }) => void) | null;
20	  onend: (() => void) | null;
21	};
22	
23	export function getSpeechRecognitionCtor(): (new () => SpeechRecognitionLike) | null {
24	  if (typeof window === "undefined") return null;
25	  const w = window as unknown as {
26	    SpeechRecognition?: new () => SpeechRecognitionLike;
27	    webkitSpeechRecognition?: new () => SpeechRecognitionLike;
28	  };
29	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
30	}
31	
32	/**
33	 * Live voice equalizer — a few bars that react to the real mic level via a Web
34	 * Audio AnalyserNode. Owns its own rAF + AudioContext and tears them down when
35	 * the stream goes away.
36	 */
37	export function VoiceMeter({ stream }: { stream: MediaStream | null }) {
38	  const canvasRef = useRef<HTMLCanvasElement>(null);
39	  useEffect(() => {
40	    if (!stream) return;
41	    const canvas = canvasRef.current;
42	    if (!canvas) return;
43	    const ctx2d = canvas.getContext("2d");
44	    if (!ctx2d) return;
45	    let raf = 0;
46	    let audioCtx: AudioContext | null = null;
47	    try {
48	      const AC =
49	        window.AudioContext ||
50	        (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
51	      if (!AC) return;
52	      audioCtx = new AC();
53	      const src = audioCtx.createMediaStreamSource(stream);
54	      const analyser = audioCtx.createAnalyser();
55	      analyser.fftSize = 128;
56	      analyser.smoothingTimeConstant = 0.75;
57	      src.connect(analyser);
58	      const bins = new Uint8Array(analyser.frequencyBinCount);
59	      const BARS = 5;
60	      const step = Math.max(1, Math.floor(bins.length / BARS));
61	      const draw = () => {
62	        analyser.getByteFrequencyData(bins);
63	        const w = canvas.width;
64	        const h = canvas.height;
65	        ctx2d.clearRect(0, 0, w, h);
66	        const bw = w / BARS;
67	        for (let i = 0; i < BARS; i++) {
68	          let sum = 0;
69	          for (let j = 0; j < step; j++) sum += bins[i * step + j] ?? 0;
70	          const v = sum / step / 255;
71	          const bh = Math.max(2, v * h);
72	          ctx2d.fillStyle = "#8a70fb";
73	          ctx2d.fillRect(i * bw + bw * 0.25, (h - bh) / 2, bw * 0.5, bh);
74	        }
75	        raf = requestAnimationFrame(draw);
76	      };
77	      draw();
78	    } catch {
79	      /* no meter */
80	    }
81	    return () => {
82	      if (raf) cancelAnimationFrame(raf);
83	      try {
84	        void audioCtx?.close();
85	      } catch {
86	        /* ignore */
87	      }
88	    };
89	  }, [stream]);
90	  return <canvas ref={canvasRef} width={46} height={16} className="h-4 w-[46px]" aria-hidden />;
91	}
92	
93	/**
94	 * Claude-style live dictation hook. `setText(next)` receives the full text
95	 * (existing input + everything spoken so far) as it streams; `toggle(current)`
96	 * starts/stops, seeding from the current input. Auto-restarts across pauses so
97	 * it behaves like a held session, and exposes the mic stream for the equalizer.
98	 */
99	export function useVoiceDictation(setText: (next: string) => void) {
100	  const [supported, setSupported] = useState(false);
101	  const [listening, setListening] = useState(false);
102	  const [error, setError] = useState<string | null>(null);
103	  const [stream, setStream] = useState<MediaStream | null>(null);
104	
105	  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
106	  const wantRef = useRef(false);
107	  const baseRef = useRef("");
108	  const committedRef = useRef("");
109	  const streamRef = useRef<MediaStream | null>(null);
110	  const setTextRef = useRef(setText);
111	  useEffect(() => {
112	    setTextRef.current = setText;
113	  }, [setText]);
114	
115	  useEffect(() => {
116	    setSupported(getSpeechRecognitionCtor() !== null);
117	  }, []);
118	
119	  const stop = useCallback(() => {
120	    wantRef.current = false;
121	    try {
122	      recognitionRef.current?.stop();
123	    } catch {
124	      /* ignore */
125	    }
126	    if (streamRef.current) {
127	      for (const t of streamRef.current.getTracks()) {
128	        try {
129	          t.stop();
130	        } catch {
131	          /* ignore */
132	        }
133	      }
134	      streamRef.current = null;
135	    }
136	    setStream(null);
137	    setListening(false);
138	  }, []);
139	
140	  const toggle = useCallback(
141	    async (currentText: string) => {
142	      const Ctor = getSpeechRecognitionCtor();
143	      if (!Ctor) {
144	        setError("Voice input isn't supported in this browser — try Chrome or Edge.");
145	        return;
146	      }
147	      if (listening) {
148	        stop();
149	        return;
150	      }
151	      setError(null);
152	      try {
153	        const s = await navigator.mediaDevices.getUserMedia({ audio: true });
154	        streamRef.current = s;
155	        setStream(s);
156	      } catch {
157	        /* meter optional */
158	      }
159	      baseRef.current = currentText;
160	      committedRef.current = currentText;
161	      wantRef.current = true;
162	      const rec = new Ctor();
163	      rec.lang = "en-US";
164	      rec.continuous = true;
165	      rec.interimResults = true;
166	      rec.onresult = (ev) => {
167	        let spoken = "";
168	        for (let i = 0; i < ev.results.length; i++) spoken += ev.results[i][0].transcript;
169	        const base = baseRef.current;
170	        const next = (base ? base + " " : "") + spoken.trim();
171	        committedRef.current = next;
172	        setTextRef.current(next);
173	      };
174	      rec.onerror = (e) => {
175	        const code = e?.error ?? "";
176	        if (code === "not-allowed" || code === "service-not-allowed") {
177	          setError("Microphone access is blocked. Allow it for this site in your browser settings, then try again.");
178	          stop();
179	        } else if (code === "audio-capture") {
180	          setError("No microphone was found. Check that one is connected.");
181	          stop();
182	        } else if (code && code !== "no-speech" && code !== "aborted") {
183	          setError("Voice input isn't available right now.");
184	          stop();
185	        }
186	      };
187	      rec.onend = () => {
188	        if (wantRef.current) {
189	          baseRef.current = committedRef.current;
190	          try {
191	            rec.start();
192	          } catch {
193	            stop();
194	          }
195	        } else {
196	          setListening(false);
197	        }
198	      };
199	      recognitionRef.current = rec;
200	      setListening(true);
201	      try {
202	        rec.start();
203	      } catch {
204	        setError("Couldn't start voice input. Check that a microphone is connected.");
205	        stop();
206	      }
207	    },
208	    [listening, stop]
209	  );
210	
211	  useEffect(() => () => stop(), [stop]);
212	
213	  return { supported, listening, error, stream, toggle };
214	}
