20	};
21	
22	export type ServerOption = { id: string; hostname: string };
23	
24	/** Volume states in which no attach/detach/delete action should be offered. */
25	function isBusy(status: string): boolean {
26	  return status === "PENDING" || status === "DELETING";
27	}
28	
29	function StatusLabel({ status }: { status: string }) {
30	  return <StatusDot status={status} />;
31	}
