33	// ---------------------------------------------------------------------------
34	// Create form
35	// ---------------------------------------------------------------------------
36	
37	function CreateVolume({ perGbCents }: { perGbCents: number }) {
38	  const [name, setName] = useState("");
39	  const [size, setSize] = useState(10);
40	  const [error, setError] = useState<string | null>(null);
41	  const [pending, start] = useTransition();
42	
43	  const monthly = Math.max(0, Math.round(size)) * perGbCents;
44	
45	  return (
46	    <div className="card p-5">
47	      <h3 className="text-base font-semibold">New volume</h3>
48	      <p className="mt-1 text-sm text-slate-400">
49	        Order an add-on disk, then attach it to any of your running servers.
50	      </p>
51	      <div className="mt-4 flex flex-wrap items-end gap-3">
52	        <div>
53	          <label className="label">Name</label>
54	          <input
55	            className="input w-56"
56	            value={name}
57	            onChange={(e) => setName(e.target.value)}
58	            placeholder="data-disk"
59	            maxLength={40}
60	            disabled={pending}
61	          />
62	        </div>
63	        <div>
64	          <label className="label">Size (GB)</label>
65	          <input
66	            className="input w-32"
67	            type="number"
68	            min={1}
69	            max={2000}
70	            value={size}
71	            onChange={(e) => setSize(Number(e.target.value))}
72	            disabled={pending}
73	          />
74	        </div>
75	        <div className="pb-1 text-sm text-slate-400">
76	          <span className="font-semibold text-slate-100">{fmtMoney(monthly)}</span> / month
77	        </div>
78	        <button
79	          className="btn-primary"
80	          disabled={pending || name.trim().length < 2 || size < 1}
81	          onClick={() =>
82	            start(async () => {
83	              setError(null);
84	              const res = await orderVolume(name.trim(), size);
85	              if (res?.error) setError(res.error);
86	              else {
87	                setName("");
88	                setSize(10);
89	              }
90	            })
91	          }
92	        >
93	          {pending ? "Ordering…" : "Order volume"}
94	        </button>
95	      </div>
96	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
97	      <p className="mt-2 text-xs text-slate-500">
98	        Billed monthly at {fmtMoney(perGbCents)} per GB. Charged now from your wallet.
99	      </p>
100	    </div>
101	  );
102	}
103	
104	// ---------------------------------------------------------------------------
105	// Row actions (attach / detach / delete)
106	// ---------------------------------------------------------------------------
107	
108	function VolumeActions({
109	  volume,
110	  servers,
111	}: {
112	  volume: VolumeRow;
113	  servers: ServerOption[];
114	}) {
115	  const [target, setTarget] = useState("");
116	  const [error, setError] = useState<string | null>(null);
117	  const [pending, start] = useTransition();
118	
119	  const run = (fn: () => Promise<{ error?: string }>, confirmMsg?: string) => {
120	    if (confirmMsg && !window.confirm(confirmMsg)) return;
121	    start(async () => {
122	      setError(null);
123	      const res = await fn();
124	      if (res?.error) setError(res.error);
125	    });
126	  };
127	
128	  const busy = isBusy(volume.status);
129	  // A volume that already holds data is pinned to its server; only offer that one.
130	  const options = volume.serverId
131	    ? servers.filter((s) => s.id === volume.serverId)
132	    : servers;
133	
134	  return (
135	    <div className="flex flex-col items-end gap-2">
136	      <div className="flex items-center gap-2">
137	        {error && <span className="text-xs text-red-400">{error}</span>}
138	
139	        {volume.status === "DETACHED" && (
140	          <>
141	            <select
142	              className="input w-44 py-1.5 text-xs"
143	              value={target}
144	              onChange={(e) => setTarget(e.target.value)}
145	              disabled={pending || options.length === 0}
146	            >
147	              <option value="">
148	                {options.length === 0 ? "No running servers" : "Attach to…"}
149	              </option>
150	              {options.map((s) => (
151	                <option key={s.id} value={s.id}>
152	                  {s.hostname}
153	                </option>
154	              ))}
155	            </select>
156	            <button
157	              className="btn-secondary px-3 py-1 text-xs"
158	              disabled={pending || !target}
159	              onClick={() => run(() => attachVolume(volume.id, target))}
160	            >
161	              Attach
162	            </button>
163	          </>
164	        )}
165	
166	        {volume.status === "ATTACHED" && (
167	          <button
168	            className="btn-secondary px-3 py-1 text-xs"
169	            disabled={pending}
170	            onClick={() =>
171	              run(
172	                () => detachVolume(volume.id),
173	                `Detach "${volume.name}" from ${volume.serverName ?? "its server"}? Data is preserved.`
174	              )
175	            }
176	          >
177	            Detach
178	          </button>
179	        )}
180	
181	        <button
182	          className="btn-danger px-3 py-1 text-xs"
183	          disabled={pending || busy}
184	          onClick={() =>
185	            run(
186	              () => deleteVolume(volume.id),
187	              `Delete volume "${volume.name}" (${volume.sizeGB} GB)? This permanently destroys its data and cannot be undone.`
188	            )
189	          }
190	        >
191	          Delete
192	        </button>
193	      </div>
194	    </div>
195	  );
196	}
