255	// ---------------------------------------------------------------------------
256	// Compact panel for a single server page
257	// ---------------------------------------------------------------------------
258	
259	export function ServerVolumesPanel({
260	  serverId,
261	  serverHostname,
262	  serverRunning,
263	  attached,
264	  available,
265	}: {
266	  serverId: string;
267	  serverHostname: string;
268	  serverRunning: boolean;
269	  /** Volumes currently attached to this server. */
270	  attached: VolumeRow[];
271	  /** Caller's DETACHED volumes that can be attached here (already ownership-filtered). */
272	  available: VolumeRow[];
273	}) {
274	  const [target, setTarget] = useState("");
275	  const [error, setError] = useState<string | null>(null);
276	  const [pending, start] = useTransition();
277	
278	  const attachable = useMemo(
279	    () => available.filter((v) => !v.serverId || v.serverId === serverId),
280	    [available, serverId]
281	  );
282	
283	  const run = (fn: () => Promise<{ error?: string }>, confirmMsg?: string) => {
284	    if (confirmMsg && !window.confirm(confirmMsg)) return;
285	    start(async () => {
286	      setError(null);
287	      const res = await fn();
288	      if (res?.error) setError(res.error);
289	    });
290	  };
291	
292	  return (
293	    <div className="card p-5">
294	      <div className="flex items-center justify-between">
295	        <div>
296	          <h3 className="text-base font-semibold">Block storage</h3>
297	          <p className="mt-1 text-sm text-slate-400">Add-on disks attached to this server.</p>
298	        </div>
299	      </div>
300	
301	      {attached.length > 0 && (
302	        <div className="mt-4 space-y-2">
303	          {attached.map((v) => (
304	            <div
305	              key={v.id}
306	              className="flex items-center justify-between rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2"
307	            >
308	              <div className="text-sm">
309	                <span className="font-medium text-slate-100">{v.name}</span>{" "}
310	                <span className="text-slate-400">· {v.sizeGB} GB</span>
311	              </div>
312	              <div className="flex items-center gap-2">
313	                <StatusLabel status={v.status} />
314	                <button
315	                  className="btn-secondary px-3 py-1 text-xs"
316	                  disabled={pending || isBusy(v.status)}
317	                  onClick={() =>
318	                    run(
319	                      () => detachVolume(v.id),
320	                      `Detach "${v.name}" from ${serverHostname}? Data is preserved.`
321	                    )
322	                  }
323	                >
324	                  Detach
325	                </button>
326	              </div>
327	            </div>
328	          ))}
329	        </div>
330	      )}
331	
332	      <div className="mt-4 flex flex-wrap items-center gap-2">
333	        <select
334	          className="input w-52 py-1.5 text-xs"
335	          value={target}
336	          onChange={(e) => setTarget(e.target.value)}
337	          disabled={pending || !serverRunning || attachable.length === 0}
338	        >
339	          <option value="">
340	            {attachable.length === 0 ? "No available volumes" : "Attach a volume…"}
341	          </option>
342	          {attachable.map((v) => (
343	            <option key={v.id} value={v.id}>
344	              {v.name} ({v.sizeGB} GB)
345	            </option>
346	          ))}
347	        </select>
348	        <button
349	          className="btn-secondary px-3 py-1 text-xs"
350	          disabled={pending || !target || !serverRunning}
351	          onClick={() => run(() => attachVolume(target, serverId))}
352	        >
353	          Attach
354	        </button>
355	        {!serverRunning && (
356	          <span className="text-xs text-slate-500">Server must be running to attach.</span>
357	        )}
358	      </div>
359	
360	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
361	      {attached.length === 0 && (
362	        <p className="mt-3 text-xs text-slate-500">No volumes attached yet.</p>
363	      )}
364	    </div>
365	  );
366	}
