3	import { useState } from "react";
4	import {
5	  orderNxCloud,
6	  revealNxcloudAdminPassword,
7	  resetNxcloudAdminPassword,
8	  retryNxcloud,
9	  terminateNxcloud,
10	  type NxCloudInstanceView,
11	} from "@/lib/actions-nxcloud";
12	import { Badge, EmptyState, StatusDot, fmtMoney } from "@/components/ui/primitives";
13	import { ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
14	import { TermLadder } from "@/components/customer/TermLadder";
15	
16	type PlanView = {
17	  id: string;
18	  slug: string;
19	  name: string;
20	  priceCents: number;
21	  storageGB: number;
22	  ramMB: number;
23	  vcpu: number;
24	  collabora: boolean;
25	  talk: boolean;
26	  featured: boolean;
27	  tagline: string;
28	};
29	
30	function storageLabel(gb: number): string {
31	  return gb >= 1000 ? `${gb / 1000} TB` : `${gb} GB`;
32	}
33	
34	export function NxcloudClient({
35	  plans,
36	  instances,
37	  zone,
38	  orderingEnabled,
39	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
40	}: {
41	  plans: PlanView[];
42	  instances: NxCloudInstanceView[];
43	  zone: string;
44	  // When false, NxCloud is shown as "coming soon" — plans are visible but the
45	  // Launch flow is replaced by a waitlist notice. Ordering opens once the owner
46	  // flips `nxcloud_ordering_enabled` (after wildcard DNS + a security review).
47	  // The server action `orderNxCloud` enforces the same gate independently.
48	  orderingEnabled: boolean;
49	  /** Live admin annual discount (%), so the Annual term shows the REAL price/savings. */
50	  annualDiscountPct?: number;
51	}) {
52	  const [subdomain, setSubdomain] = useState("");
53	  const [planId, setPlanId] = useState(plans.find((p) => p.featured)?.id ?? plans[0]?.id ?? "");
54	  // Annual is the recommended, better-value default; monthly stays one click away.
55	  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
56	  const [busy, setBusy] = useState(false);
57	  const [error, setError] = useState("");
58	  const [ok, setOk] = useState("");
59	
60	  const selectedPlan = plans.find((p) => p.id === planId) ?? null;
61	
62	  async function order() {
63	    if (!planId || !subdomain.trim()) return;
64	    setBusy(true);
65	    setError("");
66	    setOk("");
67	    try {
68	      const res = await orderNxCloud(planId, subdomain.trim(), termMonths);
69	      if (res.error) setError(res.error);
70	      else {
71	        setOk("Your cloud is being set up — this takes a few minutes.");
72	        setSubdomain("");
73	        setTimeout(() => window.location.reload(), 900);
74	      }
75	    } catch {
76	      setError("Something went wrong. Your wallet was not charged — try again.");
77	    } finally {
78	      setBusy(false);
79	    }
80	  }
81	
82	  return (
83	    <div className="space-y-8">
