47	  extraDiskGB: number;
48	  pricePerGbCents: number;
49	  /** ISO string of the current term end, or null (free/admin servers). */
50	  expiresAt: string | null;
51	  isFree: boolean;
52	  walletBalanceCents: number;
53	  disabled?: boolean;
54	}) {
55	  const maxAdd = maxAddableExtraDiskGB(planDiskGB, extraDiskGB);
56	  const [addGB, setAddGB] = useState(0);
57	  const [error, setError] = useState<string | null>(null);
58	  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
59	  const [pending, start] = useTransition();
60	  // Apply the wallet balance by default whenever there's something to apply.
61	  const [useWallet, setUseWallet] = useState(walletBalanceCents > 0);
62	
63	  const currentTotal = effectiveDiskGB(planDiskGB, extraDiskGB);
64	  const newTotal = currentTotal + addGB;
65	  const monthlyCents = extraDiskCentsAt(addGB, pricePerGbCents);
66	
67	  // Estimated prorated charge (mirrors diskExpandQuote on the server). The server
68	  // recomputes authoritatively; this only drives the copy + button.
69	  // The prorated charge, from the SAME two functions `diskExpandQuote` charges
70	  // through (lib/disk-expand.ts) — not a copy of their arithmetic.
71	  //
72	  // This block used to hold its own `MS_PER_AVG_MONTH` and its own inline
73	  // formula, making it the FOURTH derivation of one number. That matters more
74	  // here than almost anywhere: this is the figure the customer reads and
75	  // consents to in the confirm dialog, before any money moves. Every money bug
76	  // this codebase has shipped came from a second definition, never from a wrong
77	  // one — so there is now exactly one.
78	  const prorate =
79	    isFree || !expiresAt
80	      ? 0
81	      : extraDiskProrateCents(monthlyCents, remainingMonths(new Date(expiresAt), Date.now()));
82	
83	  // Exact wallet/card split — identical math to the server action, so the numbers
84	  // shown here are what actually gets charged.
85	  const split = walletSplit({ dueCents: prorate, balanceCents: walletBalanceCents, useWallet });
86	  const { walletApplied, cardCents } = split;
87	
88	  return (
89	    <div className="card">
90	      <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
91	        <h2 className="font-semibold">Add storage</h2>
92	        <span className="text-xs text-slate-400">
93	          {fmtMoney(pricePerGbCents)}/GB/mo
94	        </span>
95	      </div>
96	      <p className="mb-4 text-sm text-slate-400">
97	        Grow this server&apos;s own disk without changing its plan — CPU, RAM and the plan price stay
98	        exactly as they are. Currently{" "}
99	        <span className="font-semibold text-slate-200">{currentTotal} GB</span>
100	        {extraDiskGB > 0 && (
101	          <span className="text-slate-500">
102	            {" "}
103	            ({planDiskGB} GB plan + {extraDiskGB} GB added)
104	          </span>
105	        )}
106	        .
107	      </p>
108	
109	      {error && (
110	        <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
111	          {error}
112	        </div>
113	      )}
114	
115	      {maxAdd <= 0 ? (
116	        <p className="text-sm text-slate-400">
117	          This server is at the maximum disk size. Attach a block-storage volume for more space —
118	          volumes stay portable and can be detached later.
119	        </p>
120	      ) : (
121	        <>
122	          <div className="flex items-center gap-3">
123	            <input
124	              type="range"
125	              className="flex-1 accent-brand-400"
126	              min={0}
127	              max={maxAdd}
128	              step={EXTRA_DISK_STEP_GB}
129	              value={addGB}
130	              aria-label="Storage to add in GB"
131	              disabled={pending || disabled}
132	              onChange={(e) => setAddGB(Number(e.target.value))}
133	            />
134	            <div className="flex shrink-0 gap-1.5">
135	              {[10, 50, 100, 250].filter((g) => g <= maxAdd).map((g) => (
136	                <button
137	                  type="button"
138	                  key={g}
139	                  disabled={pending || disabled}
140	                  onClick={() => setAddGB(addGB === g ? 0 : g)}
141	                  className={`rounded-full px-2.5 py-1 text-[11px] font-semibold transition ${
142	                    addGB === g
143	                      ? "bg-white text-navy-950"
144	                      : "bg-white/[0.06] text-slate-300 hover:bg-white/10"
145	                  }`}
146	                >
147	                  +{g}
148	                </button>
149	              ))}
150	            </div>
151	          </div>
152	          <p className="mt-2 text-[11px] text-slate-500">
153	            {EXTRA_DISK_MIN_GB}–{maxAdd} GB in {EXTRA_DISK_STEP_GB} GB steps.
154	          </p>
155	
156	          <div className="mt-4 rounded-xl border border-amber-500/25 bg-amber-500/10 px-4 py-3 text-xs text-amber-300">
157	            {EXTRA_DISK_ONE_WAY_NOTE}
158	          </div>
159	
160	          <div className="mt-4 space-y-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
161	            {addGB > 0 && prorate > 0 && walletBalanceCents > 0 && (
162	              <label className="flex items-center justify-between gap-3 text-xs text-slate-300">
163	                <span className="flex items-center gap-2">
164	                  <input
165	                    type="checkbox"
166	                    checked={useWallet}
167	                    onChange={(e) => setUseWallet(e.target.checked)}
168	                  />
169	                  Apply my balance ({fmtMoney(walletBalanceCents)})
170	                </span>
171	                <span className="text-slate-500">{useWallet ? "applied" : "off"}</span>
172	              </label>
173	            )}
174	            <div className="flex flex-wrap items-center justify-between gap-3">
175	              <p className="text-xs text-slate-400">
176	                {addGB > 0 ? (
177	                  <>
178	                    Disk grows to <span className="font-semibold text-slate-200">{newTotal} GB</span>{" "}
179	                    and adds <span className="font-semibold">{fmtMoney(monthlyCents)}/mo</span> to every
180	                    renewal.
181	                    {prorate > 0 ? (
182	                      <>
183	                        {" "}
184	                        Due now: <span className="font-semibold">{fmtMoney(prorate)}</span> for the rest
185	                        of your term
186	                        {walletApplied > 0 && (
187	                          <>
188	                            {" "}
189	                            — <span className="font-semibold text-emerald-300">{fmtMoney(walletApplied)}</span>{" "}
190	                            from your wallet
191	                          </>
192	                        )}
193	                        {cardCents > 0 ? (
194	                          <>
195	                            {" "}
196	                            and <span className="font-semibold">{fmtMoney(cardCents)}</span> by secure card
197	                            checkout
198	                          </>
199	                        ) : (
200	                          <> (nothing due on card)</>
201	                        )}
202	                        .
203	                        {split.clampedForStripeMin && (
204	                          <>
205	                            {" "}
206	                            Card payments have a {fmtMoney(STRIPE_MIN_CENTS)} minimum, so{" "}
207	                            {fmtMoney(cardCents)} goes on the card.
208	                          </>
209	                        )}
210	                        {/* Whole charge is under the card floor: the wallet is the
211	                            only way to settle it, so say that instead of showing a
212	                            wallet figure the balance may not cover. */}
213	                        {split.belowStripeMin && (
214	                          walletBalanceCents >= prorate ? (
215	                            <>
216	                              {" "}
217	                              That&apos;s under the {fmtMoney(STRIPE_MIN_CENTS)} card minimum, so it comes
218	                              out of your wallet balance.
219	                            </>
220	                          ) : (
221	                            <>
222	                              {" "}
223	                              That&apos;s under the {fmtMoney(STRIPE_MIN_CENTS)} card minimum, so it can
224	                              only come from your wallet — top up to at least {fmtMoney(prorate)} first.
225	                            </>
226	                          )
227	                        )}
228	                      </>
229	                    ) : (
230	                      <> Nothing due now.</>
231	                    )}{" "}
232	                    No reboot needed — we grow the filesystem live.
233	                  </>
234	                ) : (
235	                  "Choose how much storage to add. No reboot needed — we grow the disk and filesystem live."
236	                )}
237	              </p>
238	              <button
239	                className="btn-primary"
240	                disabled={addGB <= 0 || pending || disabled}
241	                onClick={() => {
242	                  if (addGB <= 0) return;
243	                  if (
244	                    !window.confirm(
245	                      `Add ${addGB} GB to ${hostname}, taking its disk to ${newTotal} GB?\n\n` +
246	                        `This is PERMANENT — storage can be added but never removed, and it adds ` +
247	                        `${fmtMoney(monthlyCents)}/mo to every renewal for the life of this server.` +
248	                        (prorate > 0 ? `\n\nDue now: ${fmtMoney(prorate)} for the rest of your term.` : ""),
249	                    )
250	                  )
251	                    return;
252	                  start(async () => {
253	                    setError(null);
254	                    const res = await expandServerDisk(serverId, addGB, useWallet);
255	                    // Card portion > 0 → the action returns an embedded Stripe session
256	                    // we mount in a modal on THIS page (no redirect).
257	                    if (res?.checkout) {
258	                      setCheckout(res.checkout);
259	                      return;
260	                    }
261	                    if (res?.error) setError(res.error);
262	                    else setAddGB(0);
263	                  });
264	                }}
265	              >
266	                {pending
267	                  ? "Adding storage…"
268	                  : addGB <= 0
269	                    ? "Choose an amount"
270	                    : cardCents > 0
271	                      ? `Continue to payment — ${fmtMoney(cardCents)}`
272	                      : prorate > 0
273	                        ? `Add ${addGB} GB permanently — ${fmtMoney(walletApplied)}`
274	                        : `Add ${addGB} GB permanently`}
275	              </button>
276	            </div>
277	          </div>
278	        </>
279	      )}
280	      {checkout && (
281	        <StripeCheckoutModal
282	          clientSecret={checkout.clientSecret}
283	          publishableKey={checkout.publishableKey}
284	          title="Complete your storage upgrade"
285	          onClose={() => setCheckout(null)}
286	        />
287	      )}
288	    </div>
289	  );
290	}
